#include <chrono>
#include <sstream>
#include <format>
#include <string>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    using namespace std::chrono;
    const auto &database = get_tzdb();
    auto &databases = get_tzdb_list();
    assert(databases.begin() != databases.end() && !databases.front().version.empty());
    const auto *zone = locate_zone("Etc/UTC");
    assert(zone == database.locate_zone("Etc/UTC"));
    (void)database.current_zone();
    assert(!zone->name().empty());
    assert(*zone == *zone);
    sys_seconds instant{seconds{0}};
    auto local = zone->to_local(instant);
    assert(zone->to_sys(local) == instant);
    auto info = zone->get_info(instant);
    assert(info.offset == seconds{0});
    auto localInfo = zone->get_info(local);
    assert(localInfo.result == local_info::unique);
    zoned_time time{zone, instant}, copy = time;
    copy = time;
    assert(time == copy && time.get_time_zone() == zone &&
        time.get_sys_time() == instant && time.get_local_time() == local);
    assert(time.get_info().offset == seconds{0});
    assert(zoned_traits<const time_zone *>::locate_zone("Etc/UTC") == zone);
    assert(zoned_traits<const time_zone *>::default_zone());
    std::ostringstream output;
    output << time << info << localInfo << local;
    assert(!output.str().empty());
    assert(!std::format("{} {} {} {}", time, info, localInfo, local).empty());
    if (!database.links.empty()) {
        const auto &link = database.links.front();
        assert(link == link && !link.name().empty() && !link.target().empty());
    }
    const auto *ny = locate_zone("America/New_York");
    local_seconds ambiguous = local_days{2024y / November / 3} + hours{1} + minutes{30};
    assert(ny->get_info(ambiguous).result == local_info::ambiguous);
    try {
        (void)ny->to_sys(ambiguous);
        assert(false);
    } catch (const ambiguous_local_time &) {
    }
    assert(ny->to_sys(ambiguous, choose::earliest) <
        ny->to_sys(ambiguous, choose::latest));
    local_seconds missing = local_days{2024y / March / 10} + hours{2} + minutes{30};
    try {
        (void)ny->to_sys(missing);
        assert(false);
    } catch (const nonexistent_local_time &) {
    }
    // tzdb_list::erase_after mutates the process-wide list. Only remove a non-current
    // tail if one exists.
    auto first = databases.begin();
    auto next = first;
    ++next;
    if (next != databases.end())
        databases.erase_after(first);
}
